import{_ as a,o as t,c as d,a2 as s}from"./chunks/framework.D5wUhsuj.js";const u=JSON.parse('{"title":"Визуальные блоки","description":"","frontmatter":{},"headers":[],"relativePath":"features/visual-blocks/index.md","filePath":"features/visual-blocks/index.md","lastUpdated":1786090478000}'),o={name:"features/visual-blocks/index.md"};function i(c,e,n,l,r,p){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="визуальные-блоки" tabindex="-1">Визуальные блоки <a class="header-anchor" href="#визуальные-блоки" aria-label="Permalink to &quot;Визуальные блоки&quot;">​</a></h1><p>Правая панель чата: данные из <code>message.dataObjectVisual</code> попадают в <code>chatStore.lastAiAnswer</code>, <code>ChatView</code> монтирует соответствующий view.</p><p>Каталоги: <code>src/features/{map,genplan,parametric,…}/</code> + оркестрация в <code>src/features/chat/views/ChatView/</code>.</p><p>Отдельных HTTP API у модулей обычно нет — payload уже в ответе ассистента. <code>v-bind=&quot;visualData&quot;</code> пробрасывает <strong>весь</strong> объект, поэтому у view должен быть prop с тем же именем, что и ключ (<code>map</code>, <code>premises</code>, <code>images</code>, …).</p><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">component</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">is</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">visualComponent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-bind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">visualData</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">key</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">contentKey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><hr><h2 id="источник-lastaianswer" tabindex="-1">Источник <code>lastAiAnswer</code> <a class="header-anchor" href="#источник-lastaianswer" aria-label="Permalink to &quot;Источник `lastAiAnswer`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ситуация</th><th>Поведение</th></tr></thead><tbody><tr><td>Ответ ассистента (<code>sendMessage</code>)</td><td><code>lastAiAnswer = assistantMessage.dataObjectVisual</code></td></tr><tr><td>Создание чата</td><td>сразу <code>lastAiAnswer = gallery</code> (базовая галерея)</td></tr><tr><td><code>fetchChatById</code></td><td>последний message с visual, иначе fallback <code>gallery</code></td></tr><tr><td><code>openChatAtMessage</code></td><td>visual активного сообщения или <code>null</code></td></tr><tr><td><code>setLastMessage(visual)</code></td><td><code>null</code> → <code>setTimeout(0)</code> → новый visual (форс re-watch)</td></tr><tr><td><code>setBaseGallery</code></td><td>стартовая галерея (empty-state / первый visual)</td></tr><tr><td><code>clearAllChats</code></td><td><code>lastAiAnswer = null</code></td></tr></tbody></table><p><code>IChatGallery</code> — <code>{ images: […] }</code> — тот же ключ <code>images</code> → <code>SliderView</code>.</p><hr><h2 id="applyvisual-в-chatview" tabindex="-1"><code>applyVisual</code> в ChatView <a class="header-anchor" href="#applyvisual-в-chatview" aria-label="Permalink to &quot;`applyVisual` в ChatView&quot;">​</a></h2><ol><li>Источник: <code>lastMessage = getLastAiAnswer || {}</code>.</li><li>Триггеры: <code>watch(lastMessage)</code>, <code>onMounted</code>.</li><li><code>applyVisual(message)</code>: <ul><li>отменяет предыдущий <code>requestAnimationFrame</code>;</li><li>сразу <code>setVisualData</code> — пишет <code>visualData</code>, закрывает fullscreen;</li><li>на следующем кадре — <code>setVisualComponent</code> + <code>contentKey++</code> (remount).</li></ul></li></ol><p>rAF нужен, чтобы сначала отработали лента / анимация сайдбара, потом тяжёлая панель (Parametric, Map).</p><h3 id="выбор-ключа-setvisualcomponent" tabindex="-1">Выбор ключа (<code>setVisualComponent</code>) <a class="header-anchor" href="#выбор-ключа-setvisualcomponent" aria-label="Permalink to &quot;Выбор ключа (`setVisualComponent`)&quot;">​</a></h3><p>Список релевантных (порядок = приоритет при нескольких ключах):</p><p><code>images</code> → <code>premises</code> → <code>genPlan</code> → <code>genplan</code> → <code>widget</code> → <code>stocks</code> → <code>documents</code> → <code>howToBuy</code> → <code>map</code> → <code>finishing</code> → <code>advantages</code> → <code>progress</code></p><ul><li>пустой объект → выход;</li><li>ключей &gt; 1 → первый из списка приоритета, иначе <code>keys[0]</code>;</li><li>иначе → <code>keys[0]</code>.</li></ul><p><code>visualKey</code> (<code>default</code> | <code>dark</code>) влияет на тему <code>ChatAnswer</code> / <code>ChatAction</code> на мобилке в режиме <code>block</code>.</p><p><code>FullscreenImage</code> смонтирован всегда рядом; открывается через <code>provide(&#39;openFullscreenImage&#39;)</code>.</p><h3 id="сброс-панели" tabindex="-1">Сброс панели <a class="header-anchor" href="#сброс-панели" aria-label="Permalink to &quot;Сброс панели&quot;">​</a></h3><p><code>eventBus</code> <code>chat:clear-visual</code> (logout / deleteAccount): закрывает fullscreen, обнуляет <code>visualData</code>.</p><hr><h2 id="таблица-ключеи" tabindex="-1">Таблица ключей <a class="header-anchor" href="#таблица-ключеи" aria-label="Permalink to &quot;Таблица ключей&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ключ в <code>dataObjectVisual</code></th><th>Компонент</th><th><code>visualKey</code></th><th>Загрузка</th><th>Документация</th></tr></thead><tbody><tr><td><code>images</code></td><td><code>SliderView</code></td><td>default</td><td>sync</td><td><a href="./slider">Галерея (images)</a></td></tr><tr><td><code>premises</code></td><td><code>ParametricView</code></td><td>dark</td><td>async</td><td><a href="./parametric">Квартиры (premises)</a></td></tr><tr><td><code>genPlan</code> / <code>genplan</code></td><td><code>GenplanView</code></td><td>dark</td><td>sync</td><td><a href="./genplan">Генплан (genplan)</a></td></tr><tr><td><code>widget</code></td><td><code>WidgetView</code></td><td>dark</td><td>sync</td><td><a href="./widget">Виджет (widget)</a></td></tr><tr><td><code>stocks</code></td><td><code>StocksView</code></td><td>default</td><td>sync</td><td><a href="./stocks">Акции (stocks)</a></td></tr><tr><td><code>documents</code></td><td><code>DocumentsView</code></td><td>default</td><td>sync</td><td><a href="./documents">Документы (documents)</a></td></tr><tr><td><code>howToBuy</code></td><td><code>HowToBuyView</code></td><td>dark</td><td>sync</td><td><a href="./how-to-buy">Покупка / ипотека (howToBuy)</a></td></tr><tr><td><code>map</code></td><td><code>MapView</code></td><td>default</td><td>async</td><td><a href="./map">Карта (map)</a></td></tr><tr><td><code>finishing</code></td><td><code>FinishingView</code></td><td>dark</td><td>sync</td><td><a href="./finishing">Отделка (finishing)</a></td></tr><tr><td><code>advantages</code></td><td><code>AdvantagesView</code></td><td>dark</td><td>sync</td><td><a href="./advantages">Преимущества (advantages)</a></td></tr><tr><td><code>progress</code></td><td><code>ProgressView</code></td><td>dark</td><td>sync</td><td><a href="./progress">Ход строительства (progress)</a></td></tr></tbody></table><hr><h2 id="miniinfo-и-plan-не-выбирают-панель" tabindex="-1"><code>miniInfo</code> и <code>plan</code> (не выбирают панель) <a class="header-anchor" href="#miniinfo-и-plan-не-выбирают-панель" aria-label="Permalink to &quot;`miniInfo` и `plan` (не выбирают панель)&quot;">​</a></h2><p>В том же <code>dataObjectVisual</code>, но <strong>не</strong> входят в <code>allRelevantKeys</code> — правую панель не выбирают. Используются в ленте и fullscreen.</p><h3 id="miniinfo" tabindex="-1"><code>miniInfo</code> <a class="header-anchor" href="#miniinfo" aria-label="Permalink to &quot;`miniInfo`&quot;">​</a></h3><p>В <code>ChatMessage</code>: если есть <code>dataObjectVisual.miniInfo</code> → <code>ChatMiniInfo</code>.</p><table tabindex="0"><thead><tr><th>Поле</th><th>Смысл</th></tr></thead><tbody><tr><td><code>image</code> / <code>title</code> / <code>description</code> / <code>premises?</code></td><td>Превью карточки в ленте</td></tr></tbody></table><p><code>getMiniInfoType</code> — первый ключ объекта <strong>кроме</strong> <code>miniInfo</code> (тип иконки / фона); если только miniInfo → кнопка disabled.</p><p><strong>Клик по карточке:</strong></p><ol><li>Копия visual <strong>без</strong> ключа <code>miniInfo</code>.</li><li><code>chatStore.setLastMessage(object)</code> → watch → <code>applyVisual</code> → правая панель.</li><li>На mobile: <code>setActiveView(&#39;block&#39;)</code>.</li></ol><p>Для типов из <code>typesList</code> (<code>live</code>, <code>commerce</code>, <code>premises</code>, <code>map</code>, …) — SVG-фон <code>MiniInfoBackground</code>; иначе картинка <code>miniInfo.image</code>.</p><h3 id="plan" tabindex="-1"><code>plan</code> <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;`plan`&quot;">​</a></h3><p>В <code>ChatMessage</code>: <code>ChatPlan</code> при <code>dataObjectVisual.plan</code> (<code>{ image, title }</code>).</p><ul><li>Клик → <code>inject(&#39;openFullscreenImage&#39;)</code> из <code>ChatView</code> (на mobile сначала <code>setActiveView(&#39;block&#39;)</code>).</li><li>Ссылка download на <code>plan.image</code>.</li></ul><p>На mobile в <code>ChatAnswer</code> на последнем абзаце может быть превью plan (<code>isPlanOpen</code>) — это <strong>не</strong> правая панель и не <code>FullscreenImage</code>.</p><p>См. <a href="./fullscreen-image">Полноэкранный план (FullscreenImage)</a>.</p><hr><h2 id="схема-потока" tabindex="-1">Схема потока <a class="header-anchor" href="#схема-потока" aria-label="Permalink to &quot;Схема потока&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>assistant.dataObjectVisual → lastAiAnswer</span></span>\n<span class="line"><span>       ↓</span></span>\n<span class="line"><span>ChatView watch → applyVisual</span></span>\n<span class="line"><span>  → setVisualData (visualData)</span></span>\n<span class="line"><span>  → rAF → setVisualComponent + contentKey++</span></span>\n<span class="line"><span>       ↓</span></span>\n<span class="line"><span>&lt;component :is v-bind=&quot;visualData&quot; /&gt;</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Параллельно в ленте:</span></span>\n<span class="line"><span>  miniInfo → ChatMiniInfo → setLastMessage → снова applyVisual</span></span>\n<span class="line"><span>  plan     → ChatPlan → openFullscreenImage / превью в ChatAnswer</span></span></code></pre></div>',42)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
